function clipPts(ptsArr, boundaryPoints, rotation = null) {
	let segmentStarted = false;



	for (let i = 0; i < ptsArr.length; i++) {
		const pt = ptsArr[i];
		let px = pt.x;
		let py = pt.y;

		// Apply manual rotation if required
